// Apply the kitchen CSS if Card Mod misses the initial dashboard render.
(() => {
  if (!/^\/kitchen-tablet(?:\/|$)/.test(location.pathname)) return;
  const tileCss = ":host {\n  --kitchen-accent: __KITCHEN_ACCENT__;\n}\nha-card {\n  --ha-card-border-radius: 18px;\n  --ha-card-border-color: color-mix(in srgb, var(--divider-color) 70%, var(--kitchen-accent) 30%);\n  background: color-mix(in srgb, var(--card-background-color, #fff) 94%, var(--kitchen-accent) 6%);\n  box-shadow: 0 2px 6px rgb(16 33 29 / 6%);\n  transition: transform 120ms ease, box-shadow 120ms ease;\n}\nha-card:active {\n  transform: scale(.98);\n  box-shadow: none;\n}\nha-tile-container, ha-tile-info {\n  direction: rtl;\n}\n.primary {\n  font-weight: 650;\n}\n@media (prefers-reduced-motion: reduce) {\n  ha-card { transition: none; }\n  ha-card:active { transform: none; }\n}";
  const headingCss = "ha-card .container {\n  direction: rtl;\n  padding-inline: 5px;\n  box-shadow: inset 0 -1px color-mix(in srgb, var(--divider-color) 75%, transparent);\n}\n.content ha-icon {\n  color: color-mix(in srgb, var(--primary-text-color) 68%, #328274);\n}\nh2.heading {\n  font-weight: 650;\n}\nhui-entity-heading-badge {\n  display: block;\n  border-radius: 999px;\n  background: var(--secondary-background-color);\n  padding-inline: 5px;\n}";
  const accents = {"פס ארוך":"#a36b24","פס קצר":"#a36b24","ספה":"#a36b24","קמין":"#a36b24","פתיחה":"#4476aa","סגירה":"#4476aa","נעילה":"#47815e","שחרור נעילה":"#b46942","מזגן סלון":"#6879a8"};
  let attempts = 0;
  const applyStyles = () => {
    if (!/^\/kitchen-tablet(?:\/|$)/.test(location.pathname) || ++attempts > 80) return;
    const roots = [document];
    let tileCount = 0;
    while (roots.length) {
      for (const element of roots.pop().querySelectorAll('*')) {
        const root = element.shadowRoot;
        if (!root) continue;
        if (!element.matches('hui-tile-card, hui-heading-card')) {
          roots.push(root);
          continue;
        }
        const isTile = element.localName === 'hui-tile-card';
        const target = root.querySelector(isTile ? 'ha-card' : '.container');
        if (!target) continue;
        if (isTile) tileCount++;
        const current = getComputedStyle(target);
        if (root.querySelector('[data-kitchen-fallback]') ||
            (isTile ? current.getPropertyValue('--kitchen-accent').trim() : current.direction === 'rtl' && current.boxShadow !== 'none')) continue;
        const label = root.querySelector('.primary')?.textContent.trim();
        const style = document.createElement('style');
        style.setAttribute('data-kitchen-fallback', '');
        style.textContent = isTile ? tileCss.replace('__KITCHEN_ACCENT__', accents[label] || '#328274') : headingCss;
        root.append(style);
      }
    }
    if (tileCount < 17) setTimeout(applyStyles, 400);
  };
  applyStyles();
})();

// Short visual feedback for a fingertip press on the kitchen dashboard.
(() => {
  if (document.kitchenTapFeedbackInstalled) return;
  document.kitchenTapFeedbackInstalled = true;
  document.addEventListener('pointerdown', (event) => {
    if (!/^\/kitchen-tablet(?:\/|$)/.test(location.pathname) ||
        event.button !== 0 || !event.isPrimary) return;
    const control = event.composedPath().find((node) =>
      node instanceof HTMLElement &&
      node.matches('hui-tile-card, hui-entity-heading-badge'));
    if (!control) return;
    const surface = control.localName === 'hui-tile-card'
      ? control.shadowRoot?.querySelector('ha-card') : control;
    if (!surface) return;
    const accent = getComputedStyle(surface).getPropertyValue('--kitchen-accent').trim() || '#328274';
    for (const animation of surface.getAnimations()) {
      if (animation.id === 'kitchen-tap-feedback') animation.cancel();
    }
    const animation = surface.animate([
      {boxShadow: 'inset 0 0 0 3px ' + accent, filter: 'brightness(.94)'},
      {boxShadow: 'inset 0 0 0 3px transparent', filter: 'brightness(1)'},
    ], {duration: 300, easing: 'ease-out'});
    animation.id = 'kitchen-tap-feedback';
  }, {capture: true, passive: true});
})();
